     2→# ABOUTME: Test chalk parsing its own source code (lib/) for true self-hosting
     3→# ABOUTME: This is the ultimate test - can chalk parse the actual current codebase?
     4→use 5.42.0;
     5→use experimental qw(class builtin keyword_any keyword_all);
     6→use utf8;
     7→use open qw/:std :utf8/;
     8→use Test2::V0;
     9→use FindBin qw($RealBin);
    10→use lib "$RealBin/../lib";
    11→use File::Find;
    12→use Chalk::Grammar::BNF;
    13→
    14→local $| = 1;
    15→
    16→# Load the chalk.bnf grammar
    17→open my $grammar_fh, "<:utf8", "$RealBin/../grammar/chalk.bnf" or die $!;
    18→my $bnf_content = do { local $/; <$grammar_fh> };
    19→close $grammar_fh;
    20→
    21→my $chalk_grammar = Chalk::Grammar->build_from_bnf($bnf_content, "Program");
    22→
    23→# Find all .pm files in lib/
    24→my @pm_files;
    25→find(
    26→    sub {
    27→        push @pm_files, $File::Find::name if /\.pm$/ && -f;
    28→    },
    29→    "$RealBin/../lib"
    30→);
    31→
    32→@pm_files = sort @pm_files;
    33→
    34→diag "=== Self-Hosting Test: lib/ ===";
    35→diag "Testing " . scalar(@pm_files) . " files";
    36→
    37→my $passed = 0;
    38→my $failed = 0;
    39→my @failed_files;
    40→
    41→for my $file (@pm_files) {
    42→    my $relative = $file;
    43→    $relative =~ s|^.*/lib/||;
    44→
    45→    open my $fh, '<:utf8', $file or die "Cannot read $file: $!";
    46→    my $content = do { local $/; <$fh> };
    47→    close $fh;
    48→
