    53→        pass("$relative parses successfully");
    54→        $passed++;
    55→    } else {
    56→        fail("$relative should parse");
    57→        push @failed_files, $relative;
    58→        $failed++;
    59→    }
    60→}
    61→
    62→my $total = $passed + $failed;
    63→my $pct = sprintf("%.1f", ($passed / $total) * 100);
    64→
    65→diag "";
    66→diag "=== Self-Hosting Results ===";
    67→diag "Total files: $total";
    68→diag "Passed: $passed";
    69→diag "Failed: $failed";
    70→diag "Success rate: $pct%";
