);

@pm_files = sort @pm_files;

diag "=== Self-Hosting Test: lib/ ===";
diag "Testing " . scalar(@pm_files) . " files";

my $passed = 0;
my $failed = 0;
my @failed_files;

for my $file (@pm_files) {
    my $relative = $file;
