    94→    ok($store_node, 'Store node exists');
    95→    is($store_node->op, 'Store', 'Node op is Store');
    96→    is($store_node->attributes->{name}, '$x', 'Store has variable name');
    97→    is($store_node->attributes->{value}{value}, 5, 'Store has value 5');
    98→};
    99→
   100→# Test Load node creation and linkage to Store
   101→subtest 'Load node creation and Store linkage' => sub {
   102→    my $graph = Chalk::IR::Graph->new();
   103→
   104→    # Create Start node
