            left => { op => 'NodeRef', node_id => 'node_2' },
            right => { op => 'Constant', value => 10, type => 'Int' }
        }
    );
    $graph->add_node($add);

    my $return = Chalk::IR::Node->new(
        id => 'node_4',
        op => 'Return',
        inputs => ['node_1', 'node_3'],
