    for my $node_id (keys $nodes->%*) {
        my $node = $nodes->{$node_id};
        if ($node->op eq 'Load') {
            my $var_name = $node->attributes->{variable};
            my $store_id = $node->attributes->{store_id};

            if (defined($store_id)) {
                if (defined($var_name)) {
