     1→# ABOUTME: Validator for Sea of Nodes IR graphs checking SSA properties, CFG structure, dominance, and phi nodes
     2→# ABOUTME: Provides comprehensive validation infrastructure to catch IR construction errors before compilation
     3→use 5.42.0;
     4→use experimental qw(class builtin keyword_any keyword_all);
     5→use utf8;
     6→
     7→class Chalk::IR::Validator {
     8→    use Chalk::IR::Node;
     9→    use Chalk::IR::Graph;
    10→
    11→    # Main validation entry point - runs all validators
    12→    method validate_all($graph) {
    13→        my @all_errors = ();
    14→
    15→        # Run each validator and collect errors
    16→        push @all_errors, $self->validate_cfg($graph);
    17→        push @all_errors, $self->validate_single_assignment($graph);
    18→        push @all_errors, $self->validate_dominance($graph);
    19→        push @all_errors, $self->validate_phi_placement($graph);
    20→
    21→        my $success = scalar(@all_errors) == 0 ? 1 : 0;
    22→        return ($success, \@all_errors);
    23→    }
    24→
    25→    # Validate Control Flow Graph structure
    26→    method validate_cfg($graph) {
    27→        my @errors = ();
    28→
    29→        # Check: Single Start node exists
    30→        my $start_count = 0;
    31→        my $start_id = undef;
    32→        my $nodes = $graph->nodes;
    33→
    34→        for my $node_id (keys $nodes->%*) {
    35→            my $node = $nodes->{$node_id};
    36→            if ($node->op eq 'Start') {
    37→                $start_count++;
    38→                $start_id = $node_id;
    39→            }
    40→        }
    41→
    42→        if ($start_count == 0) {
    43→            push @errors, "CFG validation failed: No Start node found in graph";
    44→        }
    45→        elsif ($start_count > 1) {
    46→            push @errors, "CFG validation failed: Multiple Start nodes found ($start_count), expected exactly 1";
    47→        }
    48→
    49→        # Check: At least one Return node exists
    50→        my $return_count = 0;
    51→        for my $node_id (keys $nodes->%*) {
    52→            my $node = $nodes->{$node_id};
    53→            if ($node->op eq 'Return') {
    54→                $return_count++;
    55→            }
    56→        }
    57→
    58→        if ($return_count == 0) {
    59→            push @errors, "CFG validation failed: No Return node found in graph";
    60→        }
    61→
    62→        # Check: All nodes reachable from Start (BFS traversal)
    63→        if (defined($start_id)) {
    64→            my %reachable = ();
    65→            my @queue = ($start_id);
    66→            $reachable{$start_id} = 1;
    67→
    68→            while (scalar(@queue) > 0) {
    69→                my $current_id = shift @queue;
    70→                my $current_node = $nodes->{$current_id};
    71→
    72→                # Follow all outgoing edges (inputs reference other nodes)
    73→                # Note: In Sea of Nodes, inputs point TO this node FROM others,
    74→                # so we need to find nodes that reference this one
    75→                for my $other_id (keys $nodes->%*) {
    76→                    next if exists($reachable{$other_id});
    77→                    my $other_node = $nodes->{$other_id};
    78→
    79→                    # Check if other_node references current_node
    80→                    for my $input_id ($other_node->inputs->@*) {
    81→                        if ($input_id eq $current_id) {
    82→                            $reachable{$other_id} = 1;
    83→                            push @queue, $other_id;
    84→                            last;
    85→                        }
    86→                    }
    87→                }
    88→            }
    89→
    90→            # Report unreachable nodes
    91→            for my $node_id (keys $nodes->%*) {
    92→                if (not(exists($reachable{$node_id}))) {
    93→                    push @errors, "CFG validation failed: Node $node_id is not reachable from Start node";
    94→                }
    95→            }
    96→        }
    97→
    98→        return @errors;
    99→    }
   100→
   101→    # Validate SSA single assignment property
   102→    method validate_single_assignment($graph) {
   103→        my @errors = ();
   104→        my %assignments = ();  # variable_name => [node_ids]
   105→
   106→        my $nodes = $graph->nodes;
   107→
   108→        # Collect all Store nodes (variable assignments)
   109→        for my $node_id (keys $nodes->%*) {
   110→            my $node = $nodes->{$node_id};
   111→            if ($node->op eq 'Store') {
   112→                my $var_name = $node->attributes->{variable};
   113→                if (defined($var_name)) {
   114→                    $assignments{$var_name} //= [];
   115→                    push $assignments{$var_name}->@*, $node_id;
   116→                }
   117→            }
   118→        }
   119→
   120→        # Check for multiple assignments to same variable
   121→        for my $var_name (keys %assignments) {
   122→            my $assign_list = $assignments{$var_name};
   123→            if (scalar($assign_list->@*) > 1) {
   124→                my $node_list = join(', ', $assign_list->@*);
   125→                push @errors, "SSA violation: Variable $var_name is assigned more than once (in nodes: $node_list)";
   126→            }
   127→        }
   128→
   129→        return @errors;
   130→    }
   131→
   132→    # Compute dominance tree using Cooper/Harvey/Kennedy algorithm
   133→    method compute_dominance_tree($graph) {
   134→        my $nodes = $graph->nodes;
   135→        my %dom = ();  # node_id => immediate_dominator_id
   136→
   137→        # Find Start node
   138→        my $start_id = undef;
   139→        for my $node_id (keys $nodes->%*) {
   140→            my $node = $nodes->{$node_id};
   141→            if ($node->op eq 'Start') {
   142→                $start_id = $node_id;
   143→                last;
   144→            }
   145→        }
   146→
   147→        return \%dom unless defined($start_id);
   148→
   149→        # Build reverse graph (predecessors)
   150→        my %preds = ();  # node_id => [predecessor_ids]
   151→        for my $node_id (keys $nodes->%*) {
   152→            $preds{$node_id} = [];
   153→        }
   154→
   155→        for my $node_id (keys $nodes->%*) {
   156→            my $node = $nodes->{$node_id};
   157→            for my $input_id ($node->inputs->@*) {
   158→                if (exists($nodes->{$input_id})) {
   159→                    push $preds{$node_id}->@*, $input_id;
   160→                }
   161→            }
   162→        }
   163→
   164→        # Initialize: Start dominates itself
   165→        $dom{$start_id} = $start_id;
   166→
   167→        # Iterative dataflow until convergence
   168→        my $changed = 1;
   169→        my $max_iterations = scalar(keys $nodes->%*) * 2;
   170→        my $iterations = 0;
   171→
   172→        while ($changed) {
   173→            if ($iterations > $max_iterations) {
   174→                last;
   175→            }
   176→            $changed = 0;
   177→            $iterations++;
   178→
   179→            for my $node_id (keys $nodes->%*) {
   180→                next if $node_id eq $start_id;
   181→
   182→                my @pred_list = $preds{$node_id}->@*;
   183→                next if scalar(@pred_list) == 0;
   184→
   185→                # Find first processed predecessor
   186→                my $new_idom = undef;
   187→                for my $pred_id (@pred_list) {
   188→                    if (exists($dom{$pred_id})) {
   189→                        $new_idom = $pred_id;
   190→                        last;
   191→                    }
   192→                }
   193→
   194→                next unless defined($new_idom);
   195→
   196→                # Intersect with all other predecessors
   197→                for my $pred_id (@pred_list) {
   198→                    next if $pred_id eq $new_idom;
   199→                    next unless exists($dom{$pred_id});
   200→
   201→                    $new_idom = $self->_intersect(\%dom, $pred_id, $new_idom);
   202→                }
   203→
   204→                # Update if changed
   205→                if (not(exists($dom{$node_id}))) {
   206→                    $dom{$node_id} = $new_idom;
   207→                    $changed = 1;
   208→                }
   209→                elsif ($dom{$node_id} ne $new_idom) {
   210→                    $dom{$node_id} = $new_idom;
   211→                    $changed = 1;
   212→                }
   213→            }
   214→        }
   215→
   216→        return \%dom;
   217→    }
   218→
   219→    # Helper: Find intersection of two nodes in dominance tree
   220→    method _intersect($dom, $b1, $b2) {
   221→        my $finger1 = $b1;
   222→        my $finger2 = $b2;
   223→
   224→        while ($finger1 ne $finger2) {
   225→            # Move up dominance tree
   226→            while ($self->_node_depth($finger1) > $self->_node_depth($finger2)) {
   227→                $finger1 = $dom->{$finger1};
   228→                last unless defined($finger1);
   229→            }
   230→            last unless defined($finger1);
   231→
   232→            while ($self->_node_depth($finger2) > $self->_node_depth($finger1)) {
   233→                $finger2 = $dom->{$finger2};
   234→                last unless defined($finger2);
   235→            }
   236→            last unless defined($finger2);
   237→
   238→            if ($finger1 eq $finger2) {
   239→                last;
   240→            }
   241→
   242→            # Both at same depth, move up together
   243→            $finger1 = $dom->{$finger1};
   244→            $finger2 = $dom->{$finger2};
   245→
   246→            last unless defined($finger1);
   247→            last unless defined($finger2);
   248→        }
   249→
   250→        return $finger1;
   251→    }
   252→
   253→    # Helper: Get node depth from node_id (simple heuristic: parse number)
   254→    method _node_depth($node_id) {
   255→        return 0 unless defined($node_id);
   256→        if ($node_id =~ /node_(\d+)/) {
   257→            return $1;
   258→        }
   259→        return 0;
   260→    }
   261→
   262→    # Validate dominance property: definitions dominate uses
   263→    method validate_dominance($graph) {
   264→        my @errors = ();
   265→
   266→        my $dom_tree = $self->compute_dominance_tree($graph);
   267→        my $nodes = $graph->nodes;
   268→
   269→        # Check each Load node: its Store must exist and be valid
   270→        for my $node_id (keys $nodes->%*) {
   271→            my $node = $nodes->{$node_id};
   272→            if ($node->op eq 'Load') {
   273→                my $var_name = $node->attributes->{variable};
   274→                my $store_id = $node->attributes->{store_id};
   275→
   276→                if (defined($store_id)) {
   277→                    if (defined($var_name)) {
   278→                        # Check if store exists
   279→                        if (not(exists($nodes->{$store_id}))) {
   280→                            push @errors, "Dominance violation: Load of $var_name in $node_id references non-existent Store $store_id";
   281→                            next;
   282→                        }
   283→
   284→                        my $store_node = $nodes->{$store_id};
   285→                        if ($store_node->op ne 'Store') {
   286→                            push @errors, "Dominance violation: Load of $var_name in $node_id references $store_id which is not a Store node";
   287→                            next;
   288→                        }
   289→
   290→                        # For graphs with control flow (Region nodes), check strict dominance
   291→                        # For linear graphs (Chapters 1-4), the store_id reference is sufficient
   292→                        my $has_control_flow = $self->_has_control_flow($graph);
   293→
   294→                        if ($has_control_flow) {
   295→                            my $is_dominated = $self->_dominates($dom_tree, $store_id, $node_id);
   296→                            if (not($is_dominated)) {
   297→                                push @errors, "Dominance violation: Load of $var_name in $node_id is not dominated by its Store in $store_id";
   298→                            }
   299→                        }
   300→                    }
   301→                }
   302→            }
   303→        }
   304→
   305→        return @errors;
   306→    }
   307→
   308→    # Helper: Check if graph has control flow (Region/If nodes)
   309→    method _has_control_flow($graph) {
   310→        my $nodes = $graph->nodes;
   311→        for my $node_id (keys $nodes->%*) {
   312→            my $node = $nodes->{$node_id};
   313→            if ($node->op eq 'Region' || $node->op eq 'If') {
   314→                return 1;
   315→            }
   316→        }
   317→        return 0;
   318→    }
   319→
   320→    # Helper: Check if dominator_id dominates target_id
   321→    method _dominates($dom_tree, $dominator_id, $target_id) {
   322→        return 1 if $dominator_id eq $target_id;
   323→
   324→        # Walk up dominance tree from target
   325→        my $current = $target_id;
   326→        my $max_steps = 100;
   327→        my $steps = 0;
   328→
   329→        while (defined($current)) {
   330→            if ($steps > $max_steps) {
   331→                last;
   332→            }
   333→            $steps++;
   334→
   335→            if (exists($dom_tree->{$current})) {
   336→                $current = $dom_tree->{$current};
   337→                if (defined($current)) {
   338→                    if ($current eq $dominator_id) {
   339→                        return 1;
   340→                    }
   341→                }
   342→            }
   343→            else {
   344→                last;
   345→            }
   346→        }
   347→
   348→        return 0;
   349→    }
   350→
   351→    # Validate phi node placement (prepare for Chapter 5)
   352→    method validate_phi_placement($graph) {
   353→        my @errors = ();
   354→
   355→        my $nodes = $graph->nodes;
   356→
   357→        # Check each Phi node
   358→        for my $node_id (keys $nodes->%*) {
   359→            my $node = $nodes->{$node_id};
   360→            next unless $node->op eq 'Phi';
   361→
   362→            # Phi must be at a Region (control flow merge point)
   363→            my $phi_inputs = $node->inputs;
   364→            if (scalar($phi_inputs->@*) == 0) {
   365→                push @errors, "Phi node $node_id has no control input (must connect to Region)";
   366→                next;
   367→            }
   368→
   369→            my $region_id = $phi_inputs->[0];
   370→            if (exists($nodes->{$region_id})) {
   371→                my $region_node = $nodes->{$region_id};
   372→                if ($region_node->op ne 'Region') {
   373→                    push @errors, "Phi node $node_id is not at a Region merge point (control input is " . $region_node->op . ")";
   374→                }
   375→                else {
   376→                    # Count region predecessors
   377→                    my $region_preds = $region_node->inputs;
   378→                    my $expected_alternatives = scalar($region_preds->@*);
   379→
   380→                    # Count phi alternatives
   381→                    my $alternatives = $node->attributes->{alternatives};
   382→                    my $actual_alternatives = 0;
   383→                    if (defined($alternatives)) {
   384→                        if (ref($alternatives) eq 'ARRAY') {
   385→                            $actual_alternatives = scalar($alternatives->@*);
   386→                        }
   387→                    }
   388→
   389→                    if ($actual_alternatives != $expected_alternatives) {
   390→                        push @errors, "Phi node $node_id in node $region_id expects $expected_alternatives inputs ($expected_alternatives predecessors) but has $actual_alternatives";
   391→                    }
   392→                }
   393→            }
   394→            else {
   395→                push @errors, "Phi node $node_id references non-existent Region $region_id";
   396→            }
   397→        }
   398→
   399→        return @errors;
   400→    }
   401→}
   402→
   403→1;
   404→
   405→=pod
   406→
   407→=head1 NAME
   408→
   409→Chalk::IR::Validator - Comprehensive validation for Sea of Nodes IR graphs
   410→
   411→=head1 SYNOPSIS
   412→
   413→    use Chalk::IR::Validator;
   414→    use Chalk::IR::Graph;
   415→
   416→    my $graph = Chalk::IR::Graph->new();
   417→    # ... build graph ...
   418→
   419→    my $validator = Chalk::IR::Validator->new();
   420→    my ($success, $errors) = $validator->validate_all($graph);
   421→
   422→    if (!$success) {
   423→        for my $error (@$errors) {
   424→            warn "Validation error: $error\n";
   425→        }
   426→    }
   427→
   428→=head1 DESCRIPTION
   429→
   430→Chalk::IR::Validator provides comprehensive validation infrastructure for Sea of Nodes
   431→IR graphs. It checks critical properties required for correct compilation:
   432→
   433→=over 4
   434→
   435→=item * B<CFG Structure> - Single Start node, at least one Return node, all nodes reachable
   436→
   437→=item * B<SSA Form> - Each variable assigned exactly once (Static Single Assignment)
   438→
   439→=item * B<Dominance> - Variable uses dominated by their definitions
   440→
   441→=item * B<Phi Placement> - Phi nodes only at control flow merge points with correct arity
   442→
   443→=back
   444→
   445→This validator is designed to catch IR construction errors immediately, before they
   446→cause subtle bugs in later compilation phases.
   447→
   448→=head1 METHODS
   449→
   450→=head2 validate_all($graph)
   451→
   452→Main entry point. Runs all validators and returns results.
   453→
   454→    my ($success, $errors) = $validator->validate_all($graph);
   455→
   456→Returns:
   457→
   458→=over 4
   459→
   460→=item * C<$success> - Boolean: 1 if all validations pass, 0 if any fail
   461→
   462→=item * C<$errors> - ArrayRef of error message strings
   463→
   464→=back
   465→
   466→=head2 validate_cfg($graph)
   467→
   468→Validates Control Flow Graph structure:
   469→
   470→=over 4
   471→
   472→=item * Exactly one Start node exists
   473→
   474→=item * At least one Return node exists
   475→
   476→=item * All nodes are reachable from Start (no orphaned nodes)
   477→
   478→=back
   479→
   480→Returns: List of error messages (empty if valid)
   481→
   482→=head2 validate_single_assignment($graph)
   483→
   484→Validates SSA (Static Single Assignment) property:
   485→
   486→=over 4
   487→
   488→=item * Each variable (Store node) is assigned exactly once
   489→
   490→=back
   491→
   492→In SSA form, multiple assignments to the same variable name are prohibited.
   493→Use phi nodes at control flow merge points instead.
   494→
   495→Returns: List of error messages (empty if valid)
   496→
   497→=head2 compute_dominance_tree($graph)
   498→
   499→Computes the dominance tree using Cooper/Harvey/Kennedy algorithm.
   500→
   501→Returns: HashRef mapping C<node_id =E<gt> immediate_dominator_id>
   502→
   503→A node A dominates node B if every path from Start to B passes through A.
   504→The immediate dominator is the closest dominator (excluding the node itself).
   505→
   506→=head2 validate_dominance($graph)
   507→
   508→Validates dominance property:
   509→
   510→=over 4
   511→
   512→=item * Each variable use (Load node) is dominated by its definition (Store node)
   513→
   514→=back
   515→
   516→This ensures variables are defined before use in all possible execution paths.
   517→
   518→Returns: List of error messages (empty if valid)
   519→
   520→=head2 validate_phi_placement($graph)
   521→
   522→Validates phi node placement (Chapter 5 prerequisite):
   523→
   524→=over 4
   525→
   526→=item * Phi nodes only appear at Region (control flow merge) nodes
   527→
   528→=item * Number of phi alternatives matches number of control predecessors
   529→
   530→=item * Each phi input corresponds to an incoming control edge
   531→
   532→=back
   533→
   534→Phi nodes merge different values of a variable from different control flow paths.
   535→
   536→Returns: List of error messages (empty if valid)
   537→
   538→=head1 ERROR MESSAGES
   539→
   540→The validator produces clear, actionable error messages:
   541→
   542→=over 4
   543→
   544→=item * C<CFG validation failed: No Start node found in graph>
   545→
   546→Graph missing entry point. Every graph must have exactly one Start node.
   547→
   548→=item * C<Node node_5 is not reachable from Start node>
   549→
   550→Orphaned node detected. All nodes must be reachable via edges from Start.
   551→
   552→=item * C<SSA violation: Variable $x is assigned more than once (in nodes: node_2, node_5)>
   553→
   554→Multiple Store nodes for same variable violate SSA form. Use phi nodes instead.
   555→
   556→=item * C<Dominance violation: Load of $x in node_3 is not dominated by its Store in node_5>
   557→
   558→Variable used before definition in some control flow path.
   559→
   560→=item * C<Phi node node_7 expects 2 inputs (2 predecessors) but has 3>
   561→
   562→Phi node has wrong number of alternatives for its Region's control predecessors.
   563→
   564→=back
   565→
   566→=head1 USAGE PATTERNS
   567→
   568→=head2 Correct SSA Form
   569→
   570→    # CORRECT: Single assignment
   571→    my $store = Chalk::IR::Node->new(
   572→        op => 'Store',
   573→        attributes => { variable => '$x', value => {...} }
   574→    );
   575→
   576→    # INCORRECT: Multiple assignments (use phi instead)
   577→    my $store1 = Chalk::IR::Node->new(
   578→        op => 'Store',
   579→        attributes => { variable => '$x', value => {value => 10} }
   580→    );
   581→    my $store2 = Chalk::IR::Node->new(
   582→        op => 'Store',
   583→        attributes => { variable => '$x', value => {value => 20} }
   584→    );
   585→
   586→=head2 Correct Phi Placement
   587→
   588→    # CORRECT: Phi at Region with matching alternatives
   589→    my $region = Chalk::IR::Node->new(
   590→        op => 'Region',
   591→        inputs => ['node_then', 'node_else']  # 2 predecessors
   592→    );
   593→    my $phi = Chalk::IR::Node->new(
   594→        op => 'Phi',
   595→        inputs => ['node_region'],
   596→        attributes => {
   597→            variable => '$x',
   598→            alternatives => [
   599→                {value => 10},  # from then branch
   600→                {value => 20}   # from else branch
   601→            ]
   602→        }
   603→    );
   604→
   605→    # INCORRECT: Phi not at Region
   606→    my $phi = Chalk::IR::Node->new(
   607→        op => 'Phi',
   608→        inputs => ['node_start'],  # Not a Region!
   609→        attributes => {...}
   610→    );
   611→
   612→=head1 REFERENCES
   613→
   614→=over 4
   615→
   616→=item * Sea of Nodes IR: L<https://darksi.de/d.sea-of-nodes/>
   617→
   618→=item * SSA Form: L<https://en.wikipedia.org/wiki/Static_single-assignment_form>
   619→
   620→=item * Dominance: Cooper, Harvey, Kennedy. "A Simple, Fast Dominance Algorithm" (2001)
   621→
   622→=back
   623→
   624→=head1 AUTHOR
   625→
   626→Chalk Compiler Project
   627→
   628→=cut
