    is(scalar($phi_check->attributes->{alternatives}->@*), 2, 'Phi has two alternatives');

    my $ret_check = $graph->get_node('node_11');
    cmp_deeply($ret_check->inputs, ['node_9', 'node_10'], 'Return uses Region control and Phi value');
};

