# Test Phi node simplification when one input is dead
subtest 'Phi node simplification: single live input' => sub {
    my $graph = Chalk::IR::Graph->new();

    # Dead control constant
    my $dead_ctrl = Chalk::IR::Node->new(
        id => 'node_0',
        op => 'Constant',
        inputs => [],
