    # Live control
    my $live_ctrl = Chalk::IR::Node->new(
        id => 'node_1',
        op => 'Proj',
        inputs => [],
        attributes => { index => 0, label => 'true' }
    );
    $graph->add_node($live_ctrl);

    # Region with one dead and one live input
    my $region = Chalk::IR::Node->new(
        id => 'node_2',
        op => 'Region',
        inputs => ['node_1', 'node_0'],  # live, dead
        attributes => {}
    );
