                { op => 'NodeRef', node_id => 'node_3' },  # value from live path
                { op => 'NodeRef', node_id => 'node_4' }   # value from dead path
            ]
        }
    );
    $graph->add_node($phi);

    # Apply peephole optimization to Phi
    my $opt_phi = $phi->peephole($graph);

    # Phi should simplify to the single live value
    ok($opt_phi, 'Phi returns after peephole');
