        inputs => [$loop->id, $init_val->id],
        attributes => {},
    );
    $graph->add_node($phi_i);
    $scope->define('i', $phi_i);

    # Condition: i < 10
    my $const_10 = Chalk::IR::Node->new(
        id => 5,
        op => 'Constant',
        inputs => [],
        attributes => { value => 10 },
    );
    $graph->add_node($const_10);

    my $cmp = Chalk::IR::Node->new(
