        id => 7,
        op => 'If',
        inputs => [$loop->id, $cmp->id],
        attributes => {},
    );
    $graph->add_node($if_node);

    # True branch: loop body
    my $proj_true = Chalk::IR::Node->new(
        id => 8,
        op => 'Proj',
        inputs => [$if_node->id],
        attributes => { index => 0 },
    );
    $graph->add_node($proj_true);

    # i = i + 1
