    $graph->add_node($add);

    push $phi->inputs->@*, $add->id;
    push $loop->inputs->@*, $proj_true->id;

    my $proj_false = Chalk::IR::Node->new(
        id => 11,
        op => 'Proj',
        inputs => [$if_node->id],
        attributes => { index => 1 },
