        op => 'Loop',
        inputs => [$start->id, 3],  # Entry + backedge
        attributes => {},
    );
    $graph->add_node($loop);

    my $phi = Chalk::IR::Node->new(
        id => 3,
        op => 'Phi',
        inputs => [$loop->id, 0, 1],
