#!/usr/bin/env perl
# ABOUTME: Test Sea of Nodes Chapter 7 - While Loops
# ABOUTME: Validates loop IR nodes, loop phi nodes, and basic while loop semantics

use 5.42.0;
use Test2::V0;
use FindBin qw($RealBin);
use experimental qw(defer);
defer { done_testing() }

use lib "$RealBin/../../lib";
use lib 't/lib';
use Chalk::IR::Node;
