    $graph->add_node($start);

    my $loop = Chalk::IR::Node->new(
        id => 2,
        op => 'Loop',
        inputs => [$start->id],  # Entry
        attributes => {},
    );
    $graph->add_node($loop);

    my $const_true = Chalk::IR::Node->new(
        id => 3,
        op => 'Constant',
        inputs => [],
        attributes => { value => 1 },
    );
    $graph->add_node($const_true);

    my $if_node = Chalk::IR::Node->new(
