    $graph->add_node($init_j);
    $scope->define('j', $init_j);

    # Loop
    my $loop = Chalk::IR::Node->new(
        id => 4,
        op => 'Loop',
        inputs => [$start->id],
        attributes => {},
    );
    $graph->add_node($loop);
    $scope->push_scope();

    # Loop phis
    my $phi_i = Chalk::IR::Node->new(
        id => 5,
        op => 'Phi',
        inputs => [$loop->id, $init_i->id],
        attributes => {},
    );
    $graph->add_node($phi_i);
    $scope->define('i', $phi_i);

    my $phi_j = Chalk::IR::Node->new(
