    is scalar($phi_i->inputs->@*), 3, 'Phi i has all inputs';
    is scalar($phi_j->inputs->@*), 3, 'Phi j has all inputs';

    my $validator = Chalk::IR::Validator->new();
    my @cfg_errors = $validator->validate_cfg($graph);
    if (@cfg_errors) {
        diag("CFG errors: " . join(", ", @cfg_errors));
    }
