    my $break_true = Chalk::IR::Node->new(
        id => 5,
        op => 'Proj',
        inputs => [$if_break->id],
        attributes => { index => 0 },
    );
    $graph->add_node($break_true);

    my $break_false = Chalk::IR::Node->new(
        id => 6,
        op => 'Proj',
        inputs => [$if_break->id],
