#!/usr/bin/env perl
# ABOUTME: Test Sea of Nodes Chapter 8 - Break and Continue statements
# ABOUTME: Validates loop control flow with early exit and continue semantics

use 5.42.0;
use Test2::V0;
use FindBin qw($RealBin);
use experimental qw(defer);
defer { done_testing() }

use lib "$RealBin/../../lib";
use lib 't/lib';
use Chalk::IR::Node;
use Chalk::IR::Graph;
