#!/usr/bin/env perl
# ABOUTME: Test Sea of Nodes Chapter 9 - Global Value Numbering (GVN)
# ABOUTME: Validates redundant computation elimination and value identity optimization

use 5.42.0;
use Test2::V0;
use FindBin qw($RealBin);
use experimental qw(defer);
defer { done_testing() }

use lib "$RealBin/../../lib";
use lib 't/lib';
use Chalk::IR::Node;
use Chalk::IR::Graph;

subtest 'GVN basic concept: identical operations' => sub {
    # a = x + y; b = x + y;  ->  a = x + y; b = a;
    my $graph = Chalk::IR::Graph->new();

    my $x = Chalk::IR::Node->new(
        id => 1,
        op => 'Constant',
        inputs => [],
        attributes => { value => 5 },
    );
    $graph->add_node($x);

    my $y = Chalk::IR::Node->new(
        id => 2,
        op => 'Constant',
        inputs => [],
        attributes => { value => 3 },
    );
    $graph->add_node($y);

    # First computation: x + y
    my $add1 = Chalk::IR::Node->new(
        id => 3,
        op => 'Add',
        inputs => [$x->id, $y->id],
        attributes => {},
    );
    $graph->add_node($add1);

    # Second identical computation: x + y
    my $add2 = Chalk::IR::Node->new(
        id => 4,
        op => 'Add',
        inputs => [$x->id, $y->id],
        attributes => {},
    );
    $graph->add_node($add2);

    # Without GVN: 2 separate Add nodes
    is $graph->node_count(), 4, 'Without GVN: 4 nodes (2 constants, 2 adds)';
    isnt $add1->id, $add2->id, 'Two separate Add nodes exist';

    # With GVN: second Add should be eliminated, replaced with reference to first
    # (This will be tested after implementing GVN pass)
};

subtest 'GVN with peephole: constant folding creates opportunities' => sub {
    # (1 + 2) + (1 + 2) -> 3 + 3 -> 6
    my $graph = Chalk::IR::Graph->new();

    my $const_1 = Chalk::IR::Node->new(
        id => 1,
        op => 'Constant',
        inputs => [],
        attributes => { value => 1 },
    );
    $graph->add_node($const_1);

    my $const_2 = Chalk::IR::Node->new(
        id => 2,
        op => 'Constant',
        inputs => [],
        attributes => { value => 2 },
    );
    $graph->add_node($const_2);

    my $add1 = Chalk::IR::Node->new(
        id => 3,
        op => 'Add',
        inputs => [$const_1->id, $const_2->id],
        attributes => {},
    );
    $graph->add_node($add1);

    my $add2 = Chalk::IR::Node->new(
        id => 4,
        op => 'Add',
        inputs => [$const_1->id, $const_2->id],
        attributes => {},
    );
    $graph->add_node($add2);

    my $add3 = Chalk::IR::Node->new(
        id => 5,
        op => 'Add',
        inputs => [$add1->id, $add2->id],
        attributes => {},
    );
    $graph->add_node($add3);

    # Peephole should fold (1+2) to 3 twice, creating two Constant(3) nodes
    my $folded1 = $add1->peephole($graph);
    my $folded2 = $add2->peephole($graph);

    is $folded1->op, 'Constant', 'First (1+2) folds to Constant';
    is $folded1->attributes->{value}, 3, 'First fold result is 3';
    is $folded2->op, 'Constant', 'Second (1+2) folds to Constant';
    is $folded2->attributes->{value}, 3, 'Second fold result is 3';

    # GVN would then recognize both Constant(3) are identical
};

subtest 'Node identity: same op, same inputs, same attributes' => sub {
    my $graph = Chalk::IR::Graph->new();

    my $x = Chalk::IR::Node->new(
        id => 1,
        op => 'Constant',
        inputs => [],
        attributes => { value => 10 },
    );
    $graph->add_node($x);

    my $y = Chalk::IR::Node->new(
        id => 2,
        op => 'Constant',
        inputs => [],
        attributes => { value => 20 },
    );
    $graph->add_node($y);

    my $add1 = Chalk::IR::Node->new(
        id => 3,
        op => 'Add',
        inputs => [$x->id, $y->id],
        attributes => {},
    );
    $graph->add_node($add1);

    my $add2 = Chalk::IR::Node->new(
        id => 4,
        op => 'Add',
        inputs => [$x->id, $y->id],
        attributes => {},
    );
    $graph->add_node($add2);

    # These nodes are semantically identical
    is $add1->op, $add2->op, 'Same operation';
    is_deeply $add1->inputs, $add2->inputs, 'Same inputs';
    is_deeply $add1->attributes, $add2->attributes, 'Same attributes';
};

subtest 'Non-identical nodes: different inputs' => sub {
    my $graph = Chalk::IR::Graph->new();

    my $x = Chalk::IR::Node->new(
        id => 1,
        op => 'Constant',
        inputs => [],
        attributes => { value => 5 },
    );
    $graph->add_node($x);

    my $y = Chalk::IR::Node->new(
        id => 2,
        op => 'Constant',
        inputs => [],
        attributes => { value => 3 },
    );
    $graph->add_node($y);

    my $z = Chalk::IR::Node->new(
        id => 3,
        op => 'Constant',
        inputs => [],
        attributes => { value => 7 },
    );
    $graph->add_node($z);

    # x + y
    my $add1 = Chalk::IR::Node->new(
        id => 4,
        op => 'Add',
        inputs => [$x->id, $y->id],
        attributes => {},
    );
    $graph->add_node($add1);

    # x + z (different second input)
    my $add2 = Chalk::IR::Node->new(
        id => 5,
        op => 'Add',
        inputs => [$x->id, $z->id],
        attributes => {},
    );
    $graph->add_node($add2);

    isnt_deeply $add1->inputs, $add2->inputs, 'Different inputs -> not identical';
};

subtest 'Non-identical nodes: different operations' => sub {
    my $graph = Chalk::IR::Graph->new();

    my $x = Chalk::IR::Node->new(
        id => 1,
        op => 'Constant',
        inputs => [],
        attributes => { value => 10 },
    );
    $graph->add_node($x);

    my $y = Chalk::IR::Node->new(
        id => 2,
        op => 'Constant',
        inputs => [],
        attributes => { value => 5 },
    );
    $graph->add_node($y);

    my $add = Chalk::IR::Node->new(
        id => 3,
        op => 'Add',
        inputs => [$x->id, $y->id],
        attributes => {},
    );
    $graph->add_node($add);

    my $sub = Chalk::IR::Node->new(
        id => 4,
        op => 'Subtract',
        inputs => [$x->id, $y->id],
        attributes => {},
    );
    $graph->add_node($sub);

    isnt $add->op, $sub->op, 'Different operations -> not identical';
};

subtest 'Commutative operations: Add is commutative' => sub {
    # x + y == y + x
    my $graph = Chalk::IR::Graph->new();

    my $x = Chalk::IR::Node->new(
        id => 1,
        op => 'Constant',
        inputs => [],
        attributes => { value => 3 },
    );
    $graph->add_node($x);

    my $y = Chalk::IR::Node->new(
        id => 2,
        op => 'Constant',
        inputs => [],
        attributes => { value => 7 },
    );
    $graph->add_node($y);

    # x + y
    my $add1 = Chalk::IR::Node->new(
        id => 3,
        op => 'Add',
        inputs => [$x->id, $y->id],
        attributes => {},
    );
    $graph->add_node($add1);

    # y + x (operands swapped)
    my $add2 = Chalk::IR::Node->new(
        id => 4,
        op => 'Add',
        inputs => [$y->id, $x->id],
        attributes => {},
    );
    $graph->add_node($add2);

    # Basic GVN might not recognize commutativity
    # Advanced GVN with commutativity would recognize these as identical
    isnt_deeply $add1->inputs, $add2->inputs, 'Inputs in different order';
    # But semantically: Add(3,7) == Add(7,3)
};

subtest 'Non-commutative operations: Subtract is not commutative' => sub {
    # x - y != y - x
    my $graph = Chalk::IR::Graph->new();

    my $x = Chalk::IR::Node->new(
        id => 1,
        op => 'Constant',
        inputs => [],
        attributes => { value => 10 },
    );
    $graph->add_node($x);

    my $y = Chalk::IR::Node->new(
        id => 2,
        op => 'Constant',
        inputs => [],
        attributes => { value => 3 },
    );
    $graph->add_node($y);

    # x - y = 7
    my $sub1 = Chalk::IR::Node->new(
        id => 3,
        op => 'Subtract',
        inputs => [$x->id, $y->id],
        attributes => {},
    );
    $graph->add_node($sub1);

    # y - x = -7
    my $sub2 = Chalk::IR::Node->new(
        id => 4,
        op => 'Subtract',
        inputs => [$y->id, $x->id],
        attributes => {},
    );
    $graph->add_node($sub2);

    isnt_deeply $sub1->inputs, $sub2->inputs, 'Different input order';
    # And semantically different: Subtract(10,3) != Subtract(3,10)
};

subtest 'GVN with control flow: phi nodes complicate identity' => sub {
    # In loops, phi nodes create data dependencies that affect identity
    my $graph = Chalk::IR::Graph->new();

    my $start = Chalk::IR::Node->new(
        id => 1,
        op => 'Start',
        inputs => [],
        attributes => {},
    );
    $graph->add_node($start);

    my $loop = Chalk::IR::Node->new(
        id => 2,
        op => 'Loop',
        inputs => [$start->id],
        attributes => {},
    );
    $graph->add_node($loop);

    my $const_0 = Chalk::IR::Node->new(
        id => 3,
        op => 'Constant',
        inputs => [],
        attributes => { value => 0 },
    );
    $graph->add_node($const_0);

    my $phi = Chalk::IR::Node->new(
        id => 4,
        op => 'Phi',
        inputs => [$loop->id, $const_0->id],
        attributes => {},
    );
    $graph->add_node($phi);

    my $const_1 = Chalk::IR::Node->new(
        id => 5,
        op => 'Constant',
        inputs => [],
        attributes => { value => 1 },
    );
    $graph->add_node($const_1);

    # First: phi + 1
    my $add1 = Chalk::IR::Node->new(
        id => 6,
        op => 'Add',
        inputs => [$phi->id, $const_1->id],
        attributes => {},
    );
    $graph->add_node($add1);

    push $phi->inputs->@*, $add1->id;

    # Second: phi + 1 (looks identical but phi value changed)
    my $add2 = Chalk::IR::Node->new(
        id => 7,
        op => 'Add',
        inputs => [$phi->id, $const_1->id],
        attributes => {},
    );
    $graph->add_node($add2);

    # These appear syntactically identical
    is $add1->op, $add2->op, 'Same operation';
    is_deeply $add1->inputs, $add2->inputs, 'Same inputs syntactically';

    # But phi value changes across loop iterations
    # GVN must be careful with phi nodes
};

subtest 'Algebraic identities: x + 0 = x' => sub {
    my $graph = Chalk::IR::Graph->new();

    my $x = Chalk::IR::Node->new(
        id => 1,
        op => 'Constant',
        inputs => [],
        attributes => { value => 42 },
    );
    $graph->add_node($x);

    my $zero = Chalk::IR::Node->new(
        id => 2,
        op => 'Constant',
        inputs => [],
        attributes => { value => 0 },
    );
    $graph->add_node($zero);

    my $add = Chalk::IR::Node->new(
        id => 3,
        op => 'Add',
        inputs => [$x->id, $zero->id],
        attributes => {},
    );
    $graph->add_node($add);

    # Peephole optimization should simplify x + 0 -> x
    my $optimized = $add->peephole($graph);

    # Current peephole handles constant folding but not algebraic identities yet
    # Future enhancement: recognize x + 0 = x
    ok $optimized, 'Peephole returns a result';
};

subtest 'GVN integration with peephole: combined optimization' => sub {
    # (a + b) + (a + b) with peephole and GVN
    my $graph = Chalk::IR::Graph->new();

    my $a = Chalk::IR::Node->new(
        id => 1,
        op => 'Constant',
        inputs => [],
        attributes => { value => 5 },
    );
    $graph->add_node($a);

    my $b = Chalk::IR::Node->new(
        id => 2,
        op => 'Constant',
        inputs => [],
        attributes => { value => 10 },
    );
    $graph->add_node($b);

    my $sum1 = Chalk::IR::Node->new(
        id => 3,
        op => 'Add',
        inputs => [$a->id, $b->id],
        attributes => {},
    );
    $graph->add_node($sum1);

    my $sum2 = Chalk::IR::Node->new(
        id => 4,
        op => 'Add',
        inputs => [$a->id, $b->id],
        attributes => {},
    );
    $graph->add_node($sum2);

    my $total = Chalk::IR::Node->new(
        id => 5,
        op => 'Add',
        inputs => [$sum1->id, $sum2->id],
        attributes => {},
    );
    $graph->add_node($total);

    # Step 1: Peephole folds (5 + 10) -> 15 twice
    my $folded1 = $sum1->peephole($graph);
    my $folded2 = $sum2->peephole($graph);

    is $folded1->attributes->{value}, 15, 'First sum folds to 15';
    is $folded2->attributes->{value}, 15, 'Second sum folds to 15';

    # Step 2: GVN recognizes both Constant(15) are identical
    # Step 3: Total becomes Constant(15) + Constant(15) -> folds to Constant(30)

    # This demonstrates the power of combining optimizations
    ok 1, 'Combined optimization test structure';
};

