#!/usr/bin/env perl
# ABOUTME: Test Sea of Nodes Chapter 9 - Global Value Numbering (GVN)
# ABOUTME: Validates redundant computation elimination and value identity optimization

use 5.42.0;
use Test2::V0;
use FindBin qw($RealBin);
use experimental qw(defer);
defer { done_testing() }

use lib "$RealBin/../../lib";
use lib 't/lib';
use Chalk::IR::Node;
use Chalk::IR::Graph;

subtest 'GVN basic concept: identical operations' => sub {
    # a = x + y; b = x + y;  ->  a = x + y; b = a;
    my $graph = Chalk::IR::Graph->new();

    my $x = Chalk::IR::Node->new(
        id => 1,
        op => 'Constant',
        inputs => [],
        attributes => { value => 5 },
    );
    $graph->add_node($x);

    my $y = Chalk::IR::Node->new(
        id => 2,
        op => 'Constant',
        inputs => [],
        attributes => { value => 3 },
    );
    $graph->add_node($y);

    # First computation: x + y
    my $add1 = Chalk::IR::Node->new(
        id => 3,
        op => 'Add',
        inputs => [$x->id, $y->id],
        attributes => {},
    );
    $graph->add_node($add1);

    # Second identical computation: x + y
    my $add2 = Chalk::IR::Node->new(
        id => 4,
        op => 'Add',
        inputs => [$x->id, $y->id],
        attributes => {},
    );
    $graph->add_node($add2);

    # Without GVN: 2 separate Add nodes
    is $graph->node_count(), 4, 'Without GVN: 4 nodes (2 constants, 2 adds)';
    isnt $add1->id, $add2->id, 'Two separate Add nodes exist';

    # With GVN: second Add should be eliminated, replaced with reference to first
    # (This will be tested after implementing GVN pass)
};

subtest 'GVN with peephole: constant folding creates opportunities' => sub {
    # (1 + 2) + (1 + 2) -> 3 + 3 -> 6
    my $graph = Chalk::IR::Graph->new();

    my $const_1 = Chalk::IR::Node->new(
        id => 1,
        op => 'Constant',
        inputs => [],
        attributes => { value => 1 },
    );
    $graph->add_node($const_1);

    my $const_2 = Chalk::IR::Node->new(
        id => 2,
        op => 'Constant',
        inputs => [],
        attributes => { value => 2 },
    );
    $graph->add_node($const_2);

    my $add1 = Chalk::IR::Node->new(
        id => 3,
        op => 'Add',
        inputs => [$const_1->id, $const_2->id],
        attributes => {},
    );
    $graph->add_node($add1);

    my $add2 = Chalk::IR::Node->new(
        id => 4,
        op => 'Add',
        inputs => [$const_1->id, $const_2->id],
        attributes => {},
    );
    $graph->add_node($add2);

    my $add3 = Chalk::IR::Node->new(
        id => 5,
        op => 'Add',
        inputs => [$add1->id, $add2->id],
        attributes => {},
    );
    $graph->add_node($add3);

    # Peephole should fold (1+2) to 3 twice, creating two Constant(3) nodes
    my $folded1 = $add1->peephole($graph);
    my $folded2 = $add2->peephole($graph);

    is $folded1->op, 'Constant', 'First (1+2) folds to Constant';
    is $folded1->attributes->{value}, 3, 'First fold result is 3';
    is $folded2->op, 'Constant', 'Second (1+2) folds to Constant';
    is $folded2->attributes->{value}, 3, 'Second fold result is 3';

    # GVN would then recognize both Constant(3) are identical
};

