    $graph->add_node($y);

    # First computation: x + y
    my $add1 = Chalk::IR::Node->new(
        id => 3,
        op => 'Add',
        inputs => [$x->id, $y->id],
        attributes => {},
    );
    $graph->add_node($add1);

    # Second identical computation: x + y
    my $add2 = Chalk::IR::Node->new(
        id => 4,
        op => 'Add',
        inputs => [$x->id, $y->id],
        attributes => {},
    );
    $graph->add_node($add2);

    # Without GVN: 2 separate Add nodes
    is $graph->node_count(), 4, 'Without GVN: 4 nodes (2 constants, 2 adds)';
