subtest 'GVN with peephole: constant folding creates opportunities' => sub {
    # (1 + 2) + (1 + 2) -> 3 + 3 -> 6
    my $graph = Chalk::IR::Graph->new();

    my $const_1 = Chalk::IR::Node->new(
        id => 1,
        op => 'Constant',
        inputs => [],
        attributes => { value => 1 },
    );
    $graph->add_node($const_1);

    my $const_2 = Chalk::IR::Node->new(
        id => 2,
        op => 'Constant',
        inputs => [],
        attributes => { value => 2 },
    );
    $graph->add_node($const_2);

    my $add1 = Chalk::IR::Node->new(
        id => 3,
        op => 'Add',
        inputs => [$const_1->id, $const_2->id],
        attributes => {},
    );
    $graph->add_node($add1);

    my $add2 = Chalk::IR::Node->new(
        id => 4,
        op => 'Add',
        inputs => [$const_1->id, $const_2->id],
        attributes => {},
    );
    $graph->add_node($add2);

    my $add3 = Chalk::IR::Node->new(
        id => 5,
        op => 'Add',
        inputs => [$add1->id, $add2->id],
        attributes => {},
    );
    $graph->add_node($add3);

    # Peephole should fold (1+2) to 3 twice, creating two Constant(3) nodes
    my $folded1 = $add1->peephole($graph);
    my $folded2 = $add2->peephole($graph);

    is $folded1->op, 'Constant', 'First (1+2) folds to Constant';
