    $graph->add_node($sum1);

    my $sum2 = Chalk::IR::Node->new(
        id => 4,
        op => 'Add',
        inputs => [$a->id, $b->id],
        attributes => {},
    );
    $graph->add_node($sum2);

    my $total = Chalk::IR::Node->new(
        id => 5,
        op => 'Add',
        inputs => [$sum1->id, $sum2->id],
        attributes => {},
    );
    $graph->add_node($total);

    # Step 1: Peephole folds (5 + 10) -> 15 twice
    my $folded1 = $sum1->peephole($graph);
    my $folded2 = $sum2->peephole($graph);

    is $folded1->attributes->{value}, 15, 'First sum folds to 15';
    is $folded2->attributes->{value}, 15, 'Second sum folds to 15';

    # Step 2: GVN recognizes both Constant(15) are identical
    # Step 3: Total becomes Constant(15) + Constant(15) -> folds to Constant(30)

    # This demonstrates the power of combining optimizations
    ok 1, 'Combined optimization test structure';
};

